# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">DOĞAL SAYILARLA ÇOK ADIMLI PROBLEM STRATEJİLERİ (MAT.5.1.2)</text>\n  <rect x="20" y="48" width="320" height="190" rx="8" fill="#eff6ff" stroke="#2563eb" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Birim Kesir / Kat (Kutu) Modeli</text>\n  <rect x="45" y="88" width="55" height="26" fill="#bfdbfe" stroke="#1d4ed8" stroke-width="1.5"/>\n  <rect x="100" y="88" width="55" height="26" fill="#bfdbfe" stroke="#1d4ed8" stroke-width="1.5"/>\n  <rect x="155" y="88" width="55" height="26" fill="#bfdbfe" stroke="#1d4ed8" stroke-width="1.5"/>\n  <text x="275" y="106" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e3a8a">1. Sayı (3 kat)</text>\n  <rect x="45" y="122" width="55" height="26" fill="#dbeafe" stroke="#2563eb" stroke-width="1.5"/>\n  <text x="275" y="140" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e3a8a">2. Sayı (1 kat)</text>\n  <text x="180" y="172" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Toplam 4 kat = 480 ise → 1 kat = 480 ÷ 4 = 120</text>\n  <text x="180" y="194" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Küçük sayı = 120 · Büyük sayı = 3 × 120 = 360</text>\n  <text x="180" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Kontrol: 360 + 120 = 480 (Strateji doğrulandı)</text>\n\n  <rect x="360" y="48" width="320" height="190" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Tarife / Seçenek Karşılaştırma ve Tasarruf</text>\n  <text x="520" y="100" text-anchor="middle" font-size="11.5" fill="#14532d">• A Seçeneği: Peşin 3 000 TL + 12 × 1 250 TL</text>\n  <text x="520" y="122" text-anchor="middle" font-size="11.5" fill="#14532d">  Toplam A = 3 000 + 15 000 = 18 000 TL</text>\n  <text x="520" y="150" text-anchor="middle" font-size="11.5" fill="#14532d">• B Seçeneği: Peşin 4 500 TL + 10 × 1 300 TL</text>\n  <text x="520" y="172" text-anchor="middle" font-size="11.5" fill="#14532d">  Toplam B = 4 500 + 13 000 = 17 500 TL</text>\n  <text x="520" y="198" text-anchor="middle" font-size="11.5" fill="#14532d">• Fark: 18 000 - 17 500 = 500 TL</text>\n  <text x="520" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">B seçeneği 500 TL daha ekonomiktir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">DİKDÖRTGENİN ÇEVRE UZUNLUĞU VE KENAR İLİŞKİSİ (MAT.5.4.1)</text>\n  <rect x="20" y="48" width="320" height="190" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">Dikdörtgenin Çevre Formülü</text>\n  <rect x="90" y="92" width="180" height="70" fill="#fde68a" stroke="#b45309" stroke-width="2.5"/>\n  <text x="180" y="86" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#78350f">Uzun kenar (a = 9 cm)</text>\n  <text x="62" y="132" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#78350f">b = 5 cm</text>\n  <text x="180" y="184" text-anchor="middle" font-size="11.5" fill="#78350f">• Çevre = 2 × (Uzun Kenar + Kısa Kenar)</text>\n  <text x="180" y="204" text-anchor="middle" font-size="11.5" fill="#78350f">• Çevre = 2 × (9 + 5) = 2 × 14 = 28 cm</text>\n  <text x="180" y="224" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">Kısa + Uzun Kenar = Çevre ÷ 2 (Yarı Çevre)</text>\n\n  <rect x="360" y="48" width="320" height="190" rx="8" fill="#fdf2f8" stroke="#db2777" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Çevresi 20 cm Olan Dikdörtgenler</text>\n  <text x="520" y="96" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#831843">Yarı Çevre (Kısa + Uzun) = 20 ÷ 2 = 10 cm</text>\n  <text x="520" y="122" text-anchor="middle" font-size="11.5" fill="#831843">• 1. Dikdörtgen: Kısa = 1 cm , Uzun = 9 cm</text>\n  <text x="520" y="142" text-anchor="middle" font-size="11.5" fill="#831843">• 2. Dikdörtgen: Kısa = 2 cm , Uzun = 8 cm</text>\n  <text x="520" y="162" text-anchor="middle" font-size="11.5" fill="#831843">• 3. Dikdörtgen: Kısa = 3 cm , Uzun = 7 cm</text>\n  <text x="520" y="182" text-anchor="middle" font-size="11.5" fill="#831843">• 4. Dikdörtgen: Kısa = 4 cm , Uzun = 6 cm</text>\n  <text x="520" y="202" text-anchor="middle" font-size="11.5" fill="#831843">• 5. Dikdörtgen (Kare): Kenarlar = 5 cm ve 5 cm</text>\n  <text x="520" y="224" text-anchor="middle" font-size="11" font-weight="bold" fill="#be185d">Farklı dikdörtgenlerin çevresi aynı olabilir!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">AYNI ÇEVREYE SAHİP DİKDÖRTGENLERİN ALAN KARŞILAŞTIRMASI</text>\n  <rect x="25" y="48" width="205" height="190" rx="8" fill="#ecfeff" stroke="#0891b2" stroke-width="1.5"/>\n  <text x="127" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#0e7490">1 cm × 9 cm Dikdörtgeni</text>\n  <rect x="42" y="105" width="170" height="22" fill="#a5f3fc" stroke="#0e7490" stroke-width="2"/>\n  <text x="127" y="154" text-anchor="middle" font-size="11.5" fill="#155e75">• Çevre = 2 × (1 + 9) = 20 cm</text>\n  <text x="127" y="178" text-anchor="middle" font-size="11.5" fill="#155e75">• Alan = 1 × 9 = 9 birimkare</text>\n  <text x="127" y="214" text-anchor="middle" font-size="11" font-weight="bold" fill="#0e7490">Kenarlar uzak → Alan EN KÜÇÜK</text>\n\n  <rect x="247" y="48" width="205" height="190" rx="8" fill="#f5f3ff" stroke="#7c3aed" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#5b21b6">3 cm × 7 cm Dikdörtgeni</text>\n  <rect x="285" y="92" width="130" height="48" fill="#ddd6fe" stroke="#5b21b6" stroke-width="2"/>\n  <text x="350" y="162" text-anchor="middle" font-size="11.5" fill="#4c1d95">• Çevre = 2 × (3 + 7) = 20 cm</text>\n  <text x="350" y="186" text-anchor="middle" font-size="11.5" fill="#4c1d95">• Alan = 3 × 7 = 21 birimkare</text>\n  <text x="350" y="214" text-anchor="middle" font-size="11" font-weight="bold" fill="#5b21b6">Kenarlar yaklaştıkça alan büyür.</text>\n\n  <rect x="470" y="48" width="205" height="190" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="572" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">5 cm × 5 cm Karesi</text>\n  <rect x="532" y="84" width="80" height="64" fill="#bbf7d0" stroke="#15803d" stroke-width="2"/>\n  <text x="572" y="166" text-anchor="middle" font-size="11.5" fill="#14532d">• Çevre = 2 × (5 + 5) = 20 cm</text>\n  <text x="572" y="188" text-anchor="middle" font-size="11.5" fill="#14532d">• Alan = 5 × 5 = 25 birimkare</text>\n  <text x="572" y="214" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Kenarlar eşit → Alan EN BÜYÜK</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
